  "jxg.preview_first":      "Paste some code to preview first.",

  "jxg.prompt_intro":       "You are generating a CLASSIC, STANDALONE JSXGraph graphic (testable on its own in a\nbrowser). Don't worry about STACK/Moodle: I will convert your\ncode myself afterwards (syntax [[jsxgraph]], divid, {#…#}) — no need to know it.",
  "jxg.prompt_rules_header":"━━ RULES ━━",
  "jxg.prompt_rule1":       "1. Complete, standalone structure:\n   <div id=\"box\" style=\"width:{w};height:{h};\"></div>\n   <script src=\"https://cdn.jsdelivr.net/npm/jsxgraph/distrib/jsxgraphcore.js\"></script>\n   <script>\n   var board = JXG.JSXGraph.initBoard('box', {…});\n   … your code …\n   </script>",
  "jxg.prompt_rule2":       "2. Name the board variable EXACTLY \"board\" and the container EXACTLY\n   \"box\" (as in the skeleton below).",
  "jxg.prompt_rule3":       "3. If you use one of the variables listed below, declare it with an\n   example value AND the comment // POOLVAR: name on the SAME line\n   (e.g. var a = 3; // POOLVAR: a) — that's what lets me link it\n   automatically after conversion.",
  "jxg.prompt_rule4":       "4. Wrap the drawing in board.suspendUpdate() / board.unsuspendUpdate().",
  "jxg.prompt_rule5_interactive": "5. This graphic is INTERACTIVE: the points the student must be able to move\n   are normal, draggable JSXGraph points (NOT fixed:true). Right after\n   the board.create('point', …) line of EACH interactive point, add a\n   comment // BIND: variableName (e.g. // BIND: ans1) indicating which\n   STACK answer variable it corresponds to — I will wire up\n   stack_jxg.bind_point myself after conversion.",
  "jxg.prompt_rule5_display":     "5. This graphic is DISPLAY ONLY (not interactive): every JSXGraph\n   object MUST have {fixed:true, highlight:false, visible:true}\n   (all three — STACK needs visible:true in addition to fixed:true).",
  "jxg.prompt_config_header":"━━ COORDINATE SYSTEM CONFIGURATION (follow exactly) ━━",
  "jxg.prompt_window":      "Window: x from {xmin} to {xmax}, y from {ymin} to {ymax}",
  "jxg.prompt_options":     "Options: {opts}",
  "jxg.prompt_vars_header": "━━ AVAILABLE VARIABLES ━━",
  "jxg.prompt_var_line":    "  {n}  →  var {n} = <example value>; // POOLVAR: {n}",
  "jxg.prompt_no_vars":     "(no variable defined in the pool for this quiz)",
  "jxg.prompt_skeleton_header": "━━ REFERENCE SKELETON (use this exact config for initBoard) ━━",
  "jxg.prompt_request_header":  "━━ REQUEST ━━",
  "jxg.prompt_no_desc":     "(no description provided)",
  "jxg.prompt_draw_here":   "/* --- drawing here --- */",
  "jxg.prompt_reticule_comment": "/* --- crosshair: crossed lines + coordinates on hover --- */",
  "jxg.prompt_footer":      "Reply ONLY with the code (div + script), ready to paste and test in\na browser, wrapped in a markdown code block (```html at the start, ```\nat the end) — otherwise some chat interfaces will execute the HTML/JS\ninstead of displaying it as text. No explanation before or after.",
