  "match.prompt_ctx_sous":       ", sub-subject « {sous} »",
  "match.prompt_ctx_chap":       ", chapter « {chap} »",
  "match.prompt_role":           "### ROLE\nYou are an expert instructional designer specializing in interactive assessments (Matching Questions). Your mission is to generate a concept-matching exercise structured as JSON.",
  "match.prompt_consigne_title": "### INSTRUCTIONS",
  "match.prompt_consigne":       "Generate a \"Matching\" exercise on the following subject: {subject} for an exercise in {ctx}.",
  "match.prompt_bullet_left":    "The left column (leftItems) contains concepts, specific examples, values, or concrete cases.",
  "match.prompt_bullet_right":   "The right column (rightItems) contains general categories, definitions, properties, or thresholds.",
  "match.prompt_bullet_constraint": "MANDATORY PEDAGOGICAL CONSTRAINT (NOT 1-to-1): The exercise must NOT be a simple linear correspondence. Design it so that a right-hand item is linked to several left-hand items (Many-to-One relation), or a left-hand item is associated with several right-hand properties (Many-to-Many).",
  "match.prompt_bullet_lang":    "The language to use is {lang}.",
  "match.prompt_tech_title":     "### STRICT TECHNICAL CONSTRAINTS",
  "match.prompt_tech1":          "1. OUTPUT FORMAT: Pure JSON only (no chit-chat, no markdown code block tags, just the JSON object).",
  "match.prompt_tech2":          "2. ITEM STRUCTURE: Each object in \"leftItems\" and \"rightItems\" must have exactly this structure:",
  "match.prompt_tech3":          "3. CONNECTIONS STRUCTURE: The \"connections\" array must be an array of numeric index pairs (starting at 0). Example: [[0, 0], [1, 2], [2, 2]]. Do not use objects with leftId/rightId keys.",
  "match.prompt_tech4":          "4. ASYMMETRY: The number of left-hand and right-hand items must be different. A right-hand index MUST appear several times in the \"connections\" array to validate the non-linear structure.",
  "match.prompt_tech5":          "5. JSON ESCAPING: inside strings, double every backslash (\\\\) and escape internal quotes (\\\"). Properly escape quotes in HTML attributes. The JSON must be valid as-is.",
  "match.prompt_example_title":  "### EXPECTED STRUCTURE EXAMPLE (Many-to-One asymmetric model)",
  "match.prompt_example_left1":  "Dog",
  "match.prompt_example_left2":  "Eagle",
  "match.prompt_example_left3":  "Cat",
  "match.prompt_example_right1": "Mammals",
  "match.prompt_example_right2": "Birds",
  "match.prompt_final_title":    "### FINAL CHECK (before answering)",
  "match.prompt_final_check":    "Check that: (1) the JSON is syntactically valid; (2) all backslashes are doubled and internal quotes escaped; (3) the structure (id/html/text, connections as index pairs) is respected; (4) asymmetry is present; (5) no text outside the JSON block. If you cannot meet these constraints, return an empty JSON object {}.",
  "match.prompt_task_title":     "### TASK",
  "match.prompt_task":           "Now generate the final JSON for the subject: {subject}",

