  "ineq.fb_wrong_valeur_abs": "\\(|u|\\leq c\\Leftrightarrow -c\\leq u\\leq c\\), \\(|u|>c\\Leftrightarrow u<-c\\) or \\(u>c\\). Answer: {@{tavar}@}.",
