  "lim.title":             "Function limits",
  "lim.node_limite_correcte": "Correct limit?",
  "lim.mode_aleatoire":    "Random",
  "lim.mode_fixe":         "Fixed (f(x), point and answer below)",
  "lim.scenario_lbl":      "Limit type",
  "lim.scenario_plus_inf": "lim x → +∞",
  "lim.scenario_moins_inf":"lim x → −∞",
  "lim.scenario_point_fini":"lim x → a (finite point)",
