  "lim.expr_examples_html":"<code>sin(x)/x</code>, <code>(x^2-1)/(x-1)</code>, <code>exp(x)/x^2</code>, <code>log(x)</code>…",
  "lim.tans_lbl":          "Expected answer",
  "lim.tans_examples_html":"Examples: <code>3</code>, <code>0</code>, <code>inf</code>, <code>-inf</code>, <code>%pi</code>, <code>1/2</code>",
  "lim.fbgen_auto_desc":   "The grading (formula, value) is generated automatically based on the settings chosen in Config.",
  "lim.banniere":          "Limits",
  "lim.calc_limite":       "Calculate the limit:",
  "lim.taper_inf_ou_moins_inf": "Type <code>inf</code> for \\(+\\infty\\) or <code>-inf</code> for \\(-\\infty\\).",
  "lim.taper_inf":         "Type <code>inf</code> for \\(+\\infty\\).",
  "lim.taper_moins_inf":   "Type <code>-inf</code> for \\(-\\infty\\).",
  "lim.calc_limite_indetermination": "Calculate (removing the indeterminate form):",
  "lim.calc_limite_droite": "Calculate the right-hand limit:",
  "lim.calc_limite_gauche": "Calculate the left-hand limit:",
  "lim.fb_wrong_fixe":     "<strong>Method</strong>: try direct substitution first. If you get an indeterminate form (0/0, ∞/∞, ∞−∞...), factor or simplify the expression before resuming the limit.<br>Expected answer: {@{tavar}@}.",
  "lim.fbgen_fixe":        "The requested limit is {@{tavar}@}. Check direct substitution, and in case of an indeterminate form, factor/simplify before concluding.",
  "lim.fb_wrong_plus_inf": "<strong>Method</strong>: for a limit at \\(+\\infty\\) of a quotient of polynomials, compare the degrees of the numerator and denominator (equivalent to factoring out the dominant power on both sides).<br>Here, the numerator \\({@{numvar}@}\\) has degree {@{degnvar}@} (leading coefficient {@{lcnvar}@}), and the denominator \\({@{denvar}@}\\) has degree {@{degdvar}@} (leading coefficient {@{lcdvar}@}).<br>• deg(num) &lt; deg(den) &rarr; limit 0.<br>• deg(num) = deg(den) &rarr; limit = ratio of leading coefficients.<br>• deg(num) &gt; deg(den) &rarr; infinite limit.<br>Conclusion: the limit is {@{tavar}@}.",
  "lim.fbgen_plus_inf":    "\\(\\displaystyle\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\): numerator of degree {@{degnvar}@} (leading coefficient {@{lcnvar}@}), denominator of degree {@{degdvar}@} (leading coefficient {@{lcdvar}@}).<br>\\(\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_moins_inf":"<strong>Method</strong>: for a limit at \\(-\\infty\\) of a quotient of polynomials, compare the degrees of the numerator and denominator.<br>Here, the numerator \\({@{numvar}@}\\) has degree {@{degnvar}@} (leading coefficient {@{lcnvar}@}), and the denominator \\({@{denvar}@}\\) has degree {@{degdvar}@} (leading coefficient {@{lcdvar}@}).<br>• deg(num) &lt; deg(den) &rarr; limit 0.<br>• deg(num) = deg(den) &rarr; limit = ratio of leading coefficients.<br>• deg(num) &gt; deg(den) &rarr; infinite limit (watch the sign at \\(-\\infty\\)).<br>Conclusion: the limit is {@{tavar}@}.",
  "lim.fbgen_moins_inf":   "\\(\\displaystyle\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\): numerator of degree {@{degnvar}@} (leading coefficient {@{lcnvar}@}), denominator of degree {@{degdvar}@} (leading coefficient {@{lcdvar}@}).<br>\\(\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_point_fini":"<strong>Method</strong>: numerator and denominator both vanish at \\(x={@{avar}@}\\) (indeterminate form 0/0). Factor \\((x-{@{avar}@})\\) in the numerator: \\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\).<br>Simplify with the matching factor in the denominator: \\(\\frac{(x-{@{avar}@})({@{qvar}@})}{x-{@{avar}@}}={@{qvar}@}\\).<br>All that remains is to evaluate at \\(x={@{avar}@}\\): {@{tavar}@}.",
  "lim.fbgen_point_fini":  "Factor \\((x-{@{avar}@})\\) in the numerator (\\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\)), then simplify with the denominator: what remains is \\({@{qvar}@}\\).<br>Evaluating at \\(x={@{avar}@}\\) gives \\(\\lim={@{tavar}@}\\).",
  "lim.fb_wrong_droite":   "<strong>Method</strong>: substitute \\(u=x-{@{avar}@}\\); as \\(x\\to{@{avar}@}^+\\), \\(u\\to 0^+\\) (u stays positive).<br>The expression becomes \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\).<br>As \\(u\\to 0^+\\), \\(\\sqrt{u}\\to 0^+\\) so \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fbgen_droite":      "Substitute \\(u=x-{@{avar}@}\\to 0^+\\): the expression becomes \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fb_wrong_gauche":   "<strong>Method</strong>: substitute \\(u={@{avar}@}-x\\); as \\(x\\to{@{avar}@}^-\\), \\(u\\to 0^+\\), and \\(x-{@{avar}@}=-u\\).<br>The expression becomes \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\).<br>As \\(u\\to 0^+\\), \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\), so the expression tends to \\(-\\infty\\).",
  "lim.fbgen_gauche":      "Substitute \\(u={@{avar}@}-x\\to 0^+\\), with \\(x-{@{avar}@}=-u\\): the expression becomes \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\to-\\infty\\).",

