  "osc.consigne_lbl": "Instructions:",
  "osc.consigne_periode_frequence": "Using the cursors (buttons <span style=\"color:#7c3aed;font-weight:bold;\">■ X</span> and <span style=\"color:#b91c1c;font-weight:bold;\">■ Y</span>), measure the period \\(T\\) of the <strong>{@ta{X}_type_text@}</strong> voltage, then deduce its frequency \\(f\\).",
