  "osc.fb_frequence_unite_ko": "The unit of your frequency is not an accepted unit. The expected unit was: {@teacher_unit_F{X}/2@}.",
  "osc.fb_frequence_ok": "<strong>Well done</strong> Your frequency is perfectly exact",
  "osc.fb_frequence_valeur_ko": "The numerical value (or precision) of your frequency is incorrect, you must have made a calculation error.",
  "osc.fb_frequence_unite_incoherente": "Your frequency unit is not consistent, it does not correspond to a frequency.",
  "osc.fb_frequence_coherente_trap": "Your frequency is consistent with your answer on the period but this was not the expected answer.",
  "osc.fb_frequence_incoherente": "Your frequency is not consistent with your previous answer \\( f= \\frac {1}{T} \\)",
  "osc.genfb_reponses_attendues": "🔑 Expected answers",
  "osc.genfb_q1_periode": "Q1 Period:",
  "osc.genfb_periode_explanation": "The period is the time it takes for a cyclic phenomenon to reproduce identically. On this {@ta{X}_type_text@} voltage, using the time cursors we find T = {@1.0*ta{X}_T@}",
  "osc.genfb_q2_frequence": "Q2 Frequency:",
  "osc.genfb_frequence_explanation": "Frequency is the number of times a phenomenon reproduces per second, it is calculated with \\[ f = \\frac{1}{T} \\]",
  "osc.genfb_frequence_calcul": "So we have \\[ f= \\frac {1}{ {@1.0*ta{X}_T@} }= {@ta{X}_fq@} \\]",
  "osc.consigne_y_decharge": "With <span style=\"color:#b91c1c;font-weight:bold;\">■ Y</span>, measure the amplitude of the initial voltage \\(E\\) (between the plateau and the bottom line).",
  "osc.consigne_y_charge": "With <span style=\"color:#b91c1c;font-weight:bold;\">■ Y</span>, measure the amplitude of the final voltage \\(E\\) (between the plateau and the bottom line).",
  "osc.consigne_tau_decharge": "With <span style=\"color:#7c3aed;font-weight:bold;\">■ X</span>, measure the time constant \\(\\tau\\) (between instant \\(t=0\\) and the point corresponding to 36.8% of \\(E\\)).",
  "osc.consigne_tau_charge": "With <span style=\"color:#7c3aed;font-weight:bold;\">■ X</span>, measure the time constant \\(\\tau\\) (between instant \\(t=0\\) and the point corresponding to 63.2% of \\(E\\)).",
  "osc.rc_intro": "We observe on the oscilloscope the voltage \\(u_C(t)\\) across a capacitor during its {mode}.",
  "osc.mot_decharge": "discharge",
  "osc.mot_charge": "charge",
  "osc.label_tau_mesuree": "1. Time constant \\( \\tau \\) of the circuit: ",
