  "osc.fb_tau_unite_ko": "<strong>Time constant:</strong> The unit is incorrect (expected in SI base: {@teacher_unit_tau{X}/2@}).",
  "osc.fb_tau_correcte": "<strong>Time constant:</strong> Correct.",
