  "osc.genfb_tau_explanation": "By measuring between \\(t=0\\) and the point corresponding to {pct} of the voltage, we find \\(\\tau\\) = {@ta{X}_tau@}.",
  "osc.genfb_q2_tension": "Q2 {mode} voltage:",
  "osc.genfb_tension_explanation": "By measuring the voltage plateau with the Y cursors, we find \\(E\\) = {@ta{X}_E@}.",
  "osc.retard_intro": "We observe the transmitter signal (Channel A, <span style=\"color:#2563eb;font-weight:bold;\">Blue</span>) and the receiver signal (Channel B, <span style=\"color:#dc2626;font-weight:bold;\">Red</span>).",
  "osc.retard_determinez": "Using the time cursors (■ X), determine:",
