  "osc.preview_retard": "📡 Oscilloscope — Ultrasound delay (2 channels)",
  "osc.fb_freq_unite_ko_retard": "<strong>Frequency:</strong> The unit is incorrect (expected in SI base: {@teacher_unit_f{X}/2@}).",
  "osc.fb_freq_correcte_retard": "<strong>Frequency:</strong> Correct.",
  "osc.fb_freq_trap_salve": "<strong>Frequency:</strong> You measured the period of the burst (the overall envelope), not the period of the high-frequency ultrasound signal.",
  "osc.fb_freq_valeur_ko_retard": "<strong>Frequency:</strong> The numerical value or the precision is incorrect. Precisely measure the distance of ONE small oscillation.",
  "osc.fb_retard_unite_ko": "<strong>Delay:</strong> The unit is incorrect (expected in SI base: {@teacher_unit_dt{X}/2@}).",
  "osc.fb_retard_correct": "<strong>Delay:</strong> Correct.",
  "osc.fb_retard_trap_periode": "<strong>Delay:</strong> You calculated and entered the period of the ultrasound signal (\\(T = 1/f\\)) instead of the time offset between transmission and reception.",
  "osc.fb_retard_trap_demi_periode": "<strong>Delay:</strong> You calculated half the period of the signal (\\(T/2\\)) instead of the time offset between the bursts.",
  "osc.fb_retard_valeur_ko": "<strong>Delay:</strong> The numerical value or the precision is incorrect. Place one cursor at the start of the blue burst (transmission) and the other at the start of the red burst (reception).",
  "osc.genfb_q1_frequence_retard": "Q1 Frequency:",
  "osc.genfb_frequence_retard_explanation": "By measuring ONE period of the high-frequency signal (the small oscillations), we find \\(f\\) = {@ta{X}_fc@}.",
  "osc.genfb_q2_retard": "Q2 Time delay:",
  "osc.genfb_retard_explanation": "By placing one cursor at the start of the blue burst and the other at the start of the red burst, we measure \\(\\Delta t\\) = {@ta{X}_dt@}.",
  "diff.info_fente_simple_ecran": "Single slit, direct measurement on the figure. The student moves the crosshair over the fringes to measure the width l of the central spot, then deduces lambda.",
