  "sui.q_terme_arith_intro":"Let \\((U_n)\\) be an arithmetic sequence such that:",
  "sui.q_terme_arith_ask": "Determine the expression of \\(U_n\\) as a function of \\(n\\).",
  "sui.fb_ok_terme_arith": "<strong>Perfect!</strong> The general term is correct.",
  "sui.err_signe_raison":  "Sign of the common difference reversed! \\(r=\\frac{U_{{@{kvar}@}}-U_0}{{@{kvar}@}}={@{rvar}@}\\).",
  "sui.err_confusion_uk":  "You gave \\(U_{{@{kvar}@}}\\) instead of \\(U_n\\). The expression must contain \\(n\\).",
  "sui.err_oubli_facteur_n":"Missing the factor \\(n\\)! \\(U_n=U_0+n\\times r\\).",
  "sui.fb_wrong_terme_arith":"Incorrect. \\(r=\\frac{U_{{@{kvar}@}}-U_0}{{@{kvar}@}}={@{rvar}@}\\), so \\(U_n=U_0+n\\times r\\).",
  "sui.fbgen_terme_arith": "\\(r=\\frac{U_{{@{kvar}@}}-U_0}{{@{kvar}@}}=\\frac{{@{ukmu0var}@}}{{@{kvar}@}}={@{rvar}@}\\)<br>\\(U_n=U_0+n\\times r={@{ansvar}@}\\).",
  "sui.q_terme_geo_intro": "Let \\((U_n)\\) be a geometric sequence such that \\(U_0={@{u0var}@}\\) and \\(U_{{@{kvar}@}}={@{ukvar}@}\\).",
  "sui.q_terme_geo_ask":   "Determine \\(U_n\\).",
  "sui.fb_wrong_terme_geo":"Incorrect. \\(U_n=U_0\\times q^n={@{ansvar}@}\\).",
  "sui.fbgen_terme_geo":   "Common ratio: \\(q=\\sqrt[{@{kvar}@}]{\\frac{U_{{@{kvar}@}}}{U_0}}={@{qvar}@}\\)<br>\\(U_n={@{ansvar}@}\\).",
  "sui.q_somme_arith_intro":"Let \\((U_n)\\) be arithmetic with \\(U_0={@{u0var}@}\\) and \\(r={@{rvar}@}\\).",
  "sui.q_calculer_sn":     "Compute \\(S_n=U_0+U_1+\\cdots+U_{n-1}\\).",
  "sui.fb_wrong_somme_arith":"Incorrect. \\(S_n=\\frac{n(U_0+U_{n-1})}{2}={@{ansvar}@}\\).",
  "sui.fbgen_somme_arith": "\\(U_{n-1}={@{un1var}@}\\)<br>\\(S_n=\\frac{n(U_0+U_{n-1})}{2}={@{ansvar}@}\\).",
  "sui.q_somme_geo_intro": "Let \\((U_n)\\) be geometric with \\(U_0={@{u0var}@}\\) and \\(q={@{qvar}@}\\).",
  "sui.fb_wrong_somme_geo":"Incorrect. \\(S_n=U_0\\frac{1-q^n}{1-q}={@{ansvar}@}\\).",
  "sui.fbgen_somme_geo":   "\\(S_n=U_0\\frac{1-q^n}{1-q}={@{ansvar}@}\\).",
  "sui.q_limite_geo_intro":"Let \\((U_n)\\) be geometric with \\(U_0={@{u0var}@}\\) and \\(q={@{qvar}@}\\) with \\(|q|<1\\).",
  "sui.q_limite_geo_ask":  "Compute \\(\\displaystyle\\lim_{n\\to+\\infty} U_n\\).",
