  "geo.milieu_diff_desc":  "You calculated \\(\\frac{x_A-x_B}{2}\\) instead of \\(\\frac{x_A+x_B}{2}\\). For the midpoint, you must <strong>add</strong> the coordinates.",
  "geo.calcul_incomplet_title":"Incomplete calculation!",
  "geo.milieu_nodiv_desc": "One of the coordinates is correct, but you forgot to <strong>divide by 2</strong> on another.",
  "geo.milieu_fallback_desc":"Apply the midpoint formula:<br>\\(I\\left(\\frac{x_A+x_B}{2}\\;;\\;\\frac{y_A+y_B}{2}{zterm}\\right)\\)",
  "geo.milieu_correction_desc":"The coordinates of the midpoint of a segment are given by the <strong>arithmetic mean</strong> of the coordinates of the endpoints:<br><br>\n\\[I\\left(\\frac{x_A+x_B}{2}\\;;\\;\\frac{y_A+y_B}{2}{zterm1}\\right)\\]<br>\n<strong>Application:</strong><br><br>\n\\[x_I=\\frac{{xa}+({xb})}{2}={xm}\\]\n\\[y_I=\\frac{{ya}+({yb})}{2}={ym}\\]{zterm2}<br>\nSo \\(I{I}\\).",

