  "geo.pente_z_title":     "Wrong component!",
  "geo.pente_z_desc":      "You used the \\(z\\) coordinate instead of \\(y\\). The slope in the horizontal plane is calculated only with \\(x\\) and \\(y\\): \\(\\frac{b}{a}\\).",
  "geo.pente_moins_desc":  "The numerator/denominator calculation is correct, but the final sign is wrong.",
  "geo.pente_fallback_desc":"The slope equals the ratio of the \\(y\\) component to the \\(x\\) component of the direction vector:<br>\\(p=\\frac{b}{a}\\)",
  "geo.pente_correction_desc":"The horizontal plane \\((O;\\vec{i},\\vec{j})\\) is the plane \\((xOy)\\). The projection of \\((d)\\) onto this plane is a 2D line whose slope is the one sought.<br><br>\nParametric representation of \\((d)\\): \\(x={xa}+{a}t\\), \\(y={ya}+{b}t\\), \\(z={za}+{c}t\\).<br><br>\nThe slope is therefore the quotient of the coordinates of the direction vector:<br><br>\n\\[p=\\frac{{b}}{{a}}={ta}\\]\n<em style=\"color:#64748b;\">Note: the \\(z\\) component ({c}) does not enter into the calculation of the \"2D\" slope of the line.</em>",

  "geo.ordonnee_enonce1":  "Let \\((d)\\) be the line whose Cartesian equation is \\({eq}=0\\).",
  "geo.ordonnee_enonce2":  "<strong>1.</strong> Determine the y-intercept of the line \\((d)\\).",
  "geo.ordonnee_hint_desc":"<em>Enter the exact value (e.g., 3/2 or -4).</em>",
  "geo.ordonnee_lbl":      "The y-intercept is:",
  "geo.ordonnee_ok_desc":  "This is indeed the value of \\(y\\) when \\(x=0\\).",
  "geo.ordonnee_const_title":"Confusion with the constant!",
  "geo.ordonnee_const_desc":"You gave the value of \\(c\\). Here, you must isolate \\(y\\) to find the y-intercept, or set \\(x=0\\).",
  "geo.ordonnee_sansmoins_desc":"You calculated \\(\\frac{c}{b}\\). When isolating \\(y\\), don't forget that the minus sign moves to the numerator: \\(y=\\frac{-c}{b}\\).",
  "geo.ordonnee_pente_title":"Confusion between slope and intercept!",
  "geo.ordonnee_pente_desc":"You calculated the slope \\(-\\frac{a}{b}\\). The y-intercept is the point where the line crosses the vertical axis (when \\(x=0\\)).",
  "geo.ordonnee_axe_title": "Wrong axis!",
  "geo.ordonnee_axe_desc": "You calculated the x-intercept (when \\(y=0\\)). You are asked for the y-intercept, the value of \\(y\\) when \\(x=0\\).",
  "geo.ordonnee_fallback_desc":"To find the y-intercept, you must replace \\(x\\) with \\(0\\) in the equation and solve for \\(y\\).",
  "geo.ordonnee_correction_desc":"The y-intercept corresponds to the value of \\(y\\) when the line crosses the y-axis, that is, when \\(x=0\\).<br><br>\nWe replace \\(x\\) with \\(0\\) in the equation \\({eq}=0\\):<br><br>\n\\[{a}(0)+{b}y+{c}=0\\]\n\\[{b}y+{c}=0\\implies{b}y=-{c}\\implies y=\\frac{-{c}}{{b}}\\]\n\\[y={ta}\\]<br>\nThe y-intercept of the line is therefore {ta}.",

  "geo.aire_enonce1":      "{repere}, consider the points \\(A{A}\\), \\(B{B}\\) and \\(C{C}\\).",
  "geo.aire_enonce2":      "<strong>1.</strong> Calculate the area of triangle \\(ABC\\). <em>(Round the result to \\(10^{-2}\\).)</em>",
  "geo.aire_lbl":          "\\(\\mathcal{A}(ABC)=\\)",
  "geo.aire_ok_desc":      "The area of the triangle is correctly calculated.",
  "geo.aire_para_title":   "Parallelogram area!",
  "geo.aire_para_desc":    "You calculated the norm of the cross product \\(\\vec{AB}\\times\\vec{AC}\\), the area of the parallelogram. A triangle is <strong>half</strong> of that.",
  "geo.aire_norac_desc":   "You calculated \\(\\frac{x^2+y^2+z^2}{2}\\). The norm of a vector is \\(\\sqrt{x^2+y^2+z^2}\\), don't forget this radical.",
  "geo.aire_2d_title":     "2D calculation!",
  "geo.aire_2d_desc":      "You ignored the \\(z\\) coordinate. In 3D, you must use the <strong>cross product</strong> in space to account for depth.",
  "geo.aire_fallback_3d_desc":"Apply the formula:<br>\\(\\mathcal{A}=\\frac{1}{2}\\|\\vec{AB}\\times\\vec{AC}\\|\\)<br>without forgetting the full cross product (3 coordinates) and the square root for the norm.",
  "geo.aire_fallback_2d_desc":"Apply the triangle area formula from the coordinates:<br>\\(\\mathcal{A}=\\frac{1}{2}|x_{\\vec{AB}}y_{\\vec{AC}}-y_{\\vec{AB}}x_{\\vec{AC}}|\\)",
  "geo.aire_correction_3d":"In space, the area of a triangle is half the norm of the cross product of two of its sides:<br><br>\n\\[\\mathcal{A}(ABC)=\\frac{1}{2}\\|\\vec{AB}\\times\\vec{AC}\\|\\]<br>\n<strong>1. Vectors:</strong> \\(\\vec{AB}\\begin{pmatrix}{ux}\\\\{uy}\\\\{uz}\\end{pmatrix}\\), \\(\\vec{AC}\\begin{pmatrix}{vx}\\\\{vy}\\\\{vz}\\end{pmatrix}\\)<br><br>\n<strong>2. Cross product:</strong> \\(\\vec{AB}\\times\\vec{AC}\\begin{pmatrix}{cx}\\\\{cy}\\\\{cz}\\end{pmatrix}\\)<br><br>\n<strong>3. Norm and area:</strong><br>\n\\[\\|\\vec{AB}\\times\\vec{AC}\\|=\\sqrt{{cx}^2+{cy}^2+{cz}^2}\\approx{sqrt_arr}\\]\n\\[\\mathcal{A}(ABC)=\\frac{1}{2}\\times{sqrt_arr}\\approx{ta}\\]",
  "geo.aire_correction_2d":"In the plane, the area of a triangle is calculated from the vectors \\(\\vec{AB}\\) and \\(\\vec{AC}\\):<br><br>\n\\[\\mathcal{A}(ABC)=\\frac{1}{2}|x_{\\vec{AB}}\\,y_{\\vec{AC}}-y_{\\vec{AB}}\\,x_{\\vec{AC}}|\\]<br>\n<strong>1. Vectors:</strong> \\(\\vec{AB}\\begin{pmatrix}{ux}\\\\{uy}\\end{pmatrix}\\), \\(\\vec{AC}\\begin{pmatrix}{vx}\\\\{vy}\\end{pmatrix}\\)<br><br>\n<strong>2. Calculation:</strong><br>\n\\[\\mathcal{A}(ABC)=\\frac{1}{2}|{ux}\\times{vy}-{uy}\\times{vx}|\\approx{ta}\\]",

