  "rx.genfb_label":             "Method and result:",
  "rx.fb_calc_vwrong_title":    "The equivalence volume you read is not correct.",
  "rx.fb_calc_vwrong_low":      "Your reading is too low: look for the point where the potential jumps sharply (potential jump), further along the volume axis.",
  "rx.fb_calc_vwrong_high":     "Your reading is too high: the potential jump is earlier on the curve.",
  "rx.fb_calc_vwrong_method":   "Method: Veq is the abscissa of the sharp potential jump (slope break, marked by the dotted line).",
  "rx.fb_calc_cwrong_title":    "Correct reading of Veq, but the calculation of C₂ is incorrect.",
  "rx.fb_calc_cwrong_method":   "Method: at equivalence, the exchanged amounts of matter are proportional to the electrons: n₁·C₁·Veq = n₂·C₂·V₂, so C₂ = (n₁·C₁·Veq)/(n₂·V₂).",
  "rx.fb_calc_ok":              "Correct graph reading and calculation!",
  "rx.genfb_calc_1":            "The potential jump occurs at Veq = {veq} mL.",
  "rx.genfb_calc_2":            "At equivalence: n₁·C₁·Veq = n₂·C₂·V₂, so C₂ = ({n1}×{c1}×{veq})/({n2}×{v2}) = {c2} mol/L.",
  "rx.method_equivalence_vwrong": "Veq is the volume where the curve shows a <strong>sharp potential jump</strong> (slope break): that's where the titrated reagent has just been fully consumed.",
  "rx.method_equivalence_label":  "Veq = {veq} mL (potential jump)",
  "rx.method_eo1_ewrong":       "After a <strong>large excess of titrant</strong> (V ≫ Veq), almost all the added titrant remains in oxidized form: the potential stabilizes near E°₁ (plateau after the jump).",
  "rx.method_eo1_label":        "E°₁ = {e1} V (plateau after the jump, V ≫ Veq)",
  "rx.method_eo2_ewrong":       "Just <strong>before equivalence</strong>, the titrated species is still largely present: the potential stays close to E°₂ (plateau before the jump).",
  "rx.method_eo2_label":        "E°₂ = {e2} V (plateau before the jump, V ≪ Veq)",
  "rx.method_demi_vwrong":      "Half-equivalence corresponds to <strong>V = Veq / 2</strong>, i.e. half the volume at which the potential jump occurs.",
  "rx.method_demi_ewrong":      "At half-equivalence, the concentrations of the two forms of the titrated couple are equal ([Ox₂] = [Red₂]): in the Nernst relation, the logarithmic term vanishes, so <strong>E = E°₂</strong>.",
  "rx.method_demi_label":       "Half-equivalence: V = Veq/2 = {v} mL, E = E°₂ = {e2} V",
  "rx.method_double_vwrong":    "The double-equivalence point corresponds to <strong>V = 2 × Veq</strong>: the excess titrant added then equals the initial amount of titrated species.",
  "rx.method_double_ewrong":    "In this excess, the concentrations of the two forms of the titrant couple are equal ([Ox₁] = [Red₁]): by Nernst, <strong>E = E°₁</strong>.",
  "rx.method_double_label":     "Double equivalence: V = 2·Veq = {v} mL, E = E°₁ = {e1} V",
  "rx.method_eeq_vwrong":       "The equivalence point lies exactly at the abscissa of the <strong>sharp potential jump</strong> (V = Veq).",
  "rx.method_eeq_ewrong":       "The potential at equivalence is a <strong>weighted average by exchanged electrons</strong>: Eeq = (n₁·E°₁ + n₂·E°₂)/(n₁+n₂).",
  "rx.method_eeq_label":        "Equivalence point: V = Veq = {v} mL, Eeq = {eeq} V",
