  "tpl.topo_fb_fleche_ok":   "✓ Correct reaction arrow!",
  "tpl.topo_fb_fleche_ko":   "✗ Wrong arrow. Detected: {det}, expected: {att}",
  "tpl.topo_fb_atomes_ok":   "✓ Your reaction is balanced in terms of chemical elements!",
  "tpl.topo_fb_atomes_ko":   "✗ Your reaction is not balanced in terms of chemical elements!",
  "tpl.topo_fb_charges_ok":  "✓ Your equation is electrically balanced.",
