  "opt.mic_type": "Real intermediate image, then afocal system",
  "opt.info_lentille_convergente": "✏️ The student draws at least two of the three principal rays from B using the toolbar (2-click ray, ray // axis, 3-click parallel ray), then constructs point B' by intersecting the emerging rays. The real/virtual status of each segment is corrected automatically.",
  "opt.info_lentille_divergente": "✏️ As for the converging lens, but the image is <strong>always virtual</strong>: the emerging rays diverge after the lens and must be extended backward (dashed) to construct B'.",
  "opt.info_miroir_plan": "✏️ The student draws the two principal rays from B (normal incidence, and a ray arriving at S), reflects them off the plane mirror, then constructs B' by intersecting the extended reflected rays. The image is <strong>always virtual and the same size</strong> as the object.",
  "opt.info_miroir_concave": "✏️ The student draws at least two of the four principal rays from B (// axis, through C, through F, toward S), reflects them off the mirror, then constructs B' by intersecting the reflected rays. Depending on the object's position (SA &lt; f or SA &gt; f), the image is virtual or real — the expected real/virtual status of each segment is corrected automatically.",
  "opt.info_miroir_convexe": "✏️ As for the concave mirror, but the focus F and center C are <strong>virtual</strong> (behind the mirror): the resulting image is always virtual, regardless of the object's position.",
  "opt.info_lunette_galilee": "✏️ The student constructs four principal rays: two parallel incident rays (one through the center of the objective) that converge at B&#8321; in the common focal plane, then two rays from B&#8321; toward the eyepiece, which emerge parallel (afocal system, image at infinity). Point B&#8321; is constructed with the \"Intersection\" tool.",
  "opt.info_telescope_newton": "✏️ The student constructs two parallel incident rays inclined by θ (one touching the vertex S of the primary mirror, the other offset by h) and their corresponding reflected rays (use \"Reflect about axis\" for the ray reflected at the vertex), which converge at image point B&#8321; in the mirror's focal plane. Point B&#8321; is constructed with the \"Intersection\" tool.",
  "opt.info_microscope": "✏️ The student draws at least two of the three principal rays from B through objective L&#8321;, which converge at B&#8321; (real intermediate image, constructed with \"Intersection\"), then the two rays from B&#8321; through eyepiece L&#8322;, placed so that B&#8321; is exactly in its object focal plane (setting for a normal eye): the emerging beam comes out parallel (final image at infinity).",
