  "inc.fb_ecr_unite_wrong": "Incorrect unit: break down the unit you entered into SI base units (kg, m, s, A, K, mol, cd) and compare it to the measured quantity's — confusing physical quantities or a wrong simplification causes this kind of mismatch. A valid unit would be for example {@{unitvar}@}.",
  "inc.fb_wrong": "Incorrect. Expected value: {@{tavar}@}",
  "inc.fb_wrong_ecr": "Incorrect. Expected answer: {@{tavar}@}",
  "inc.fb_wrong_moyenne": "Incorrect mean: recompute the arithmetic mean (sum of all measurements divided by their number n). Expected answer: {@{tavar}@}",
  "inc.fb_wrong_s": "Incorrect standard deviation: use the experimental standard deviation formula with n−1 measurements in the denominator (Bessel's correction), not n. Expected answer: {@{tavar}@}",
  "inc.fb_wrong_uA": "Incorrect Type A uncertainty: divide the standard deviation s by the square root of the number of measurements n (uncertainty on the mean, not on a single measurement). Expected answer: {@{tavar}@}",
  "inc.fb_wrong_uB_resolution": "Incorrect Type B uncertainty: for a resolution-based uncertainty, divide the instrument's resolution by √12 (uniform distribution over the reading interval). Expected answer: {@{tavar}@}",
  "inc.fb_wrong_uB_tolerance": "Incorrect Type B uncertainty: divide the manufacturer's tolerance (half-range) by √3 (uniform distribution). Expected answer: {@{tavar}@}",
  "inc.fb_wrong_uB_calibration": "Incorrect Type B uncertainty: divide the calibration certificate's uncertainty by its stated coverage factor k. Expected answer: {@{tavar}@}",
  "inc.fb_wrong_uB_impose": "Incorrect Type B uncertainty: this uncertainty is a given value from the problem statement, to be used as-is, with no calculation. Expected answer: {@{tavar}@}",
  "inc.fb_wrong_uc": "Incorrect combined uncertainty: combine uA and uB in quadrature (square root of the sum of squares), not by simple addition. Expected answer: {@{tavar}@}",
  "inc.fb_wrong_U": "Incorrect expanded uncertainty: recheck U = k×uc, then round it up to 1 or 2 significant figures (never round down). Expected answer: {@{tavar}@}",
  "inc.fb_ok_moyenne": "Mean correct.",
  "inc.fb_ok_s": "Standard deviation correct.",
  "inc.fb_ok_uA": "Type A uncertainty correct.",
  "inc.fb_ok_uB": "Type B uncertainty correct.",
  "inc.fb_ok_uc": "Combined uncertainty correct.",
  "inc.fb_ok_U": "Expanded uncertainty correct.",
  "inc.fbgen": "<p>Measurements: {@{lvar}@}</p><p>Mean: {@{moyvar}@}</p><p>Sample standard deviation: {@{svar}@}</p><p>Type A standard uncertainty: {@{uavar}@}</p><p>Type B standard uncertainty: {@{ubvar}@}</p><p>Combined uncertainty: {@{ucvar}@}</p><p>Expanded uncertainty: {@{uvar}@}</p>",
  "inc.fbgen_propagation": "<p>Central value: {@{moyvar}@}</p><p>Propagated uncertainty u(Y): {@{ubvar}@}</p><p>Combined uncertainty: {@{ucvar}@}</p><p>Expanded uncertainty: {@{uvar}@}</p>",

