  "cin.method_apres": "Next point (MᵢMᵢ₊₁/Δt)",
  "cin.method_symetrique": "Symmetric derivative (Mᵢ₋₁Mᵢ₊₁/2Δt)",
  "cin.iidx_title": "Velocity vector measurement point",
  "cin.iidx_hint": "Index i of the first point used: the student will draw M_iM_{i+1} (for vᵢ) then M_{i+1}M_{i+2} (for vᵢ₊₁) on the graph. An error message is shown in the preview if i is out of range for the number of digitized points.",
  "cin.iidx_lbl": "Index i of the starting point",
  "cin.fbgen_auto_desc": "The correction (magnitude vᵢ and construction of Δvᵢ) is generated automatically. This field lets you add an extra pedagogical comment.",
