  "cin.preview_unavailable_fallback": "Preview unavailable: digitize at least 3 points in the workshop and set the calibration.",
  "cin.err_not_enough_points": "At least 3 points M₀, M₁, M₂… must be digitized in the workshop to generate the question. Click other positions on the background (blank or imported image).",
  "cin.err_bad_calib": "The scale calibration is incomplete or degenerate: place 2 distinct calibration points and enter a strictly positive real distance between them.",
  "cin.err_bad_index": "The chosen index i ({iIdx}) is out of range for the number of digitized points: it must be between {iMin} and {iMax}. Adjust the « Index i of the starting point » field in the workshop{extra}.",
  "cin.err_bad_index_extra": " (the symmetric derivative method requires a point before M{iMin})",
  "cin.step1_title": "Step 1 — Displacement and velocity vectors",
  "cin.step1_instruction": "On the graph below, draw the displacement vector M<sub>{a1}</sub>M<sub>{b1}</sub> then M<sub>{a2}</sub>M<sub>{b2}</sub> (dedicated buttons), then deduce the magnitudes of velocity vectors v<sub>{i}</sub> and v<sub>{ip1}</sub> in m/s (segment duration: {dtEff} s).",
  "cin.step2_title": "Step 2 — Construction of Δv<sub>{i}</sub> using the Chasles relation",
  "cin.step2_instruction": "Once v<sub>{i}</sub> and v<sub>{ip1}</sub> are entered above, the vectors v<sub>{i}</sub> (blue, from M<sub>{i}</sub>) and v<sub>{ip1}</sub> (green, from M<sub>{ip1}</sub>) appear below. Clone them (dedicated buttons), position and orient the clones (automatic snapping when you approach an existing tip) to construct Δv<sub>{i}</sub> = v<sub>{ip1}</sub> − v<sub>{i}</sub> using the Chasles relation, then draw the result vector (red) with the dedicated button.",
