  "cin.fb_norme_ko": "Magnitude of v<sub>{i}</sub> incorrect: take the length of the vector M<sub>{a}</sub>M<sub>{b}</sub> (using the scale) and divide by {dtEff} s.",
  "cin.fb_dv_ok": "Correct construction: your vector Δv<sub>{i}</sub> does match v<sub>{ip1}</sub> − v<sub>{i}</sub>.",
  "cin.fb_dv_ko": "The drawn vector does not match v<sub>{ip1}</sub> − v<sub>{i}</sub>: redo the construction using the Chasles relation (clone v<sub>{i}</sub> and v<sub>{ip1}</sub>, place them tip-to-tail, invert if needed).",
  "cin.genfb_step1_title": "Step 1 — expected displacement vectors and velocities:",
  "cin.genfb_step1_vec": "M<sub>{a}</sub>M<sub>{b}</sub> = ({vecx} ; {vecy}) m, so v<sub>{i}</sub> = M<sub>{a}</sub>M<sub>{b}</sub> / {dtEff} = {norm} m/s.",
  "cin.genfb_step2_title": "Step 2 — construction of Δv<sub>{i}</sub> using the Chasles relation:",
  "cin.genfb_dv": "Δv<sub>{i}</sub> = v<sub>{ip1}</sub> − v<sub>{i}</sub> = ({dvx} ; {dvy}) m/s.",
  "cin.genfb_construction": "Expected construction: clone v<sub>{i}</sub> and invert the clone to get −v<sub>{i}</sub>; clone v<sub>{ip1}</sub> and snap its origin to the tip of −v<sub>{i}</sub>; the vector from the origin of −v<sub>{i}</sub> to the tip of v<sub>{ip1}</sub> is then Δv<sub>{i}</sub>.",

